HAL_StatusTypeDef HAL_UART_DMAStop(UART_HandleTypeDef *huart)
{
  /* Skip all hardware-specific operations */
  /* Original code had ATOMIC_CLEAR_BIT operations and DMA abort calls */

  /* For Tx, restore state if busy */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    huart->gState = HAL_UART_STATE_READY;
    huart->TxXferCount = 0;
  }

  /* For Rx, restore state if busy */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    huart->RxState = HAL_UART_STATE_READY;
    huart->RxXferCount = 0;
  }

  return HAL_OK;
}
